const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const states = ee.FeatureCollection('TIGER/2018/States');
    const alFeature = states.filter(ee.Filter.eq('NAME', 'Alabama')).first();
    const geom = ee.Feature(alFeature).geometry();

    // 2. Data Acquisition
    let datasetId = 'NASA/GRACE/MASS_GRIDS/LAND';
    let graceCol = ee.ImageCollection(datasetId).select('lwe_thickness');

    async function yearStats(year, collection) {
      const start = ee.Date.fromYMD(year, 1, 1);
      const end = start.advance(1, 'year');
      const col = collection.filterDate(start, end);
      const size = await col.size().getInfo();
      if (size === 0) return { year, images: 0, valid: 0, mean: null };
      const img = col.mean();
      const count = await img.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geom,
        scale: 50000,
        maxPixels: 1e9,
      }).get('lwe_thickness').getInfo();
      const mean = await img.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: geom,
        scale: 50000,
        maxPixels: 1e9,
      }).get('lwe_thickness').getInfo();
      return { year, images: size, valid: count || 0, mean };
    }

    let s2003 = await yearStats(2003, graceCol);
    let s2012 = await yearStats(2012, graceCol);

    // Recovery if needed (fallback dataset)
    if (s2003.images === 0 || s2012.images === 0) {
      try {
        const fbId = 'JPL/GRACE/MASS_GRIDS/MASCON_CRI_GRID_RL06_V02';
        const fbCol = ee.ImageCollection(fbId).select('lwe_thickness');
        const f2003 = await yearStats(2003, fbCol);
        const f2012 = await yearStats(2012, fbCol);
        if (f2003.images > 0 || f2012.images > 0) {
          datasetId = fbId;
          graceCol = fbCol;
          s2003 = f2003.images > 0 ? f2003 : s2003;
          s2012 = f2012.images > 0 ? f2012 : s2012;
        }
      } catch (e) { /* ignore fallback errors if not needed */ }
    }

    // 3. Evidence prints (concise)
    console.log('Dataset:', datasetId);
    console.log('2003 Images:', s2003.images);
    console.log('2012 Images:', s2012.images);

    // Case C1: Empty collection for one/both years
    if (s2003.images === 0 || s2012.images === 0) {
      console.log('One or both years have no images.');
      console.log('C1');
      return;
    }

    console.log('2003 Valid px:', s2003.valid, 'Mean cm:', (s2003.mean == null ? 'null' : s2003.mean.toFixed(2)));
    console.log('2012 Valid px:', s2012.valid, 'Mean cm:', (s2012.mean == null ? 'null' : s2012.mean.toFixed(2)));

    // Case C2: No valid pixels after processing
    if (!s2003.valid || !s2012.valid || s2003.valid === 0 || s2012.valid === 0) {
      console.log('No valid pixels after masking/processing.');
      console.log('C2');
      return;
    }

    // Case C3: Invalid calculation (null/NaN/out-of-range)
    const invalid = (v) => (v === null || isNaN(v) || Math.abs(v) > 1e4);
    if (invalid(s2003.mean) || invalid(s2012.mean)) {
      console.log('Invalid mean value encountered.');
      console.log('C3');
      return;
    }

    // 4. Calculation and Answer
    const diff = s2012.mean - s2003.mean; // negative means decrease
    console.log('Diff 2012-2003 (cm):', diff.toFixed(2));

    const tol = 0.1; // tolerance in cm
    if (diff < -tol) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log('Error:', (err && err.message) ? err.message : String(err));
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
